CREATE TABLE IF NOT EXISTS organizations(id text PRIMARY KEY, name text NOT NULL);
CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY, org text NOT NULL REFERENCES organizations ON DELETE CASCADE, email text UNIQUE NOT NULL, name text NOT NULL, password text NOT NULL, role text NOT NULL, verified boolean DEFAULT false);
CREATE TABLE IF NOT EXISTS credentials(token text PRIMARY KEY, uid text NOT NULL REFERENCES users ON DELETE CASCADE, purpose text NOT NULL, expires bigint NOT NULL);
CREATE INDEX IF NOT EXISTS credentials_expiry ON credentials(expires);
CREATE TABLE IF NOT EXISTS quizzes(id text PRIMARY KEY, org text NOT NULL REFERENCES organizations ON DELETE CASCADE, owner text REFERENCES users ON DELETE SET NULL, title text NOT NULL, category text NOT NULL, document jsonb NOT NULL, version integer NOT NULL DEFAULT 1, updated bigint NOT NULL);
ALTER TABLE quizzes ADD COLUMN IF NOT EXISTS kind text NOT NULL DEFAULT 'quiz';
CREATE INDEX IF NOT EXISTS quizzes_org ON quizzes(org,updated);
CREATE TABLE IF NOT EXISTS rooms(pin text PRIMARY KEY, org text NOT NULL REFERENCES organizations ON DELETE CASCADE, owner text REFERENCES users ON DELETE SET NULL, quiz text REFERENCES quizzes ON DELETE SET NULL, title text NOT NULL, snapshot jsonb NOT NULL, config jsonb NOT NULL, phase text NOT NULL DEFAULT 'waiting', position integer NOT NULL DEFAULT 0, deadline bigint NOT NULL DEFAULT 0, remaining bigint NOT NULL DEFAULT 0, revealed jsonb NOT NULL DEFAULT '[]', created bigint NOT NULL);
CREATE INDEX IF NOT EXISTS rooms_org ON rooms(org,created);
CREATE TABLE IF NOT EXISTS people(id text PRIMARY KEY, pin text NOT NULL REFERENCES rooms ON DELETE CASCADE, name text NOT NULL, token text UNIQUE NOT NULL, consent boolean NOT NULL DEFAULT false, public_photo boolean NOT NULL DEFAULT false, joined bigint NOT NULL, team text NOT NULL DEFAULT '', feedback text NOT NULL DEFAULT '');
ALTER TABLE people ADD COLUMN IF NOT EXISTS guardian_reference text NOT NULL DEFAULT '';
CREATE INDEX IF NOT EXISTS people_room ON people(pin);
CREATE TABLE IF NOT EXISTS answers(person text NOT NULL REFERENCES people ON DELETE CASCADE, q integer NOT NULL, value jsonb NOT NULL, points integer NOT NULL, correct boolean, elapsed bigint NOT NULL, PRIMARY KEY(person,q));
CREATE TABLE IF NOT EXISTS photos(id text PRIMARY KEY, person text REFERENCES people ON DELETE CASCADE, moment text NOT NULL, image bytea NOT NULL, thumb bytea NOT NULL, created bigint NOT NULL);
ALTER TABLE photos ADD COLUMN IF NOT EXISTS published boolean NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS messages(id text PRIMARY KEY, pin text REFERENCES rooms ON DELETE CASCADE, person text REFERENCES people ON DELETE CASCADE, body text NOT NULL, approved boolean DEFAULT false, created bigint NOT NULL);
CREATE TABLE IF NOT EXISTS result_links(token text PRIMARY KEY, person text UNIQUE REFERENCES people ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS votes(message text REFERENCES messages ON DELETE CASCADE, person text REFERENCES people ON DELETE CASCADE, PRIMARY KEY(message, person));
CREATE TABLE IF NOT EXISTS assets(id text PRIMARY KEY, org text REFERENCES organizations ON DELETE CASCADE,mime text NOT NULL,bytes bytea NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id text PRIMARY KEY, actor text, org text, action text NOT NULL, at bigint NOT NULL);
CREATE TABLE IF NOT EXISTS attempts(id text PRIMARY KEY,person text REFERENCES people ON DELETE CASCADE,q integer NOT NULL,request_id text NOT NULL,value jsonb NOT NULL,points integer NOT NULL,correct boolean,elapsed bigint NOT NULL,submitted bigint NOT NULL,UNIQUE(person,q,request_id));
CREATE TABLE IF NOT EXISTS approved_answers(person text,q integer,approved_value jsonb NOT NULL,PRIMARY KEY(person,q),FOREIGN KEY(person,q) REFERENCES answers(person,q) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS question_views(person text REFERENCES people ON DELETE CASCADE,q integer NOT NULL,started bigint NOT NULL,PRIMARY KEY(person,q));
CREATE TABLE IF NOT EXISTS consent_records(id text PRIMARY KEY,person text REFERENCES people ON DELETE CASCADE,allowed boolean NOT NULL,public_allowed boolean NOT NULL,recorded bigint NOT NULL);
CREATE INDEX IF NOT EXISTS consent_person ON consent_records(person,recorded);
CREATE TABLE IF NOT EXISTS settings(id text PRIMARY KEY, value jsonb NOT NULL);
ALTER TABLE answers ADD COLUMN IF NOT EXISTS marked boolean NOT NULL DEFAULT false;
ALTER TABLE users ADD COLUMN IF NOT EXISTS suspended boolean NOT NULL DEFAULT false;
ALTER TABLE assets ADD COLUMN IF NOT EXISTS owner text REFERENCES users ON DELETE SET NULL;
UPDATE assets a SET owner=d.owner FROM (SELECT DISTINCT ON (x->'asset'->>'id') x->'asset'->>'id' AS asset,q.owner FROM quizzes q,jsonb_array_elements(q.document) x WHERE q.owner IS NOT NULL AND x->'asset'->>'id' IS NOT NULL ORDER BY x->'asset'->>'id',q.updated) d WHERE a.id=d.asset AND a.owner IS NULL;
